REPLACE INTO `items` (`id`, `monday_item_id`, `board_id`, `group_id`, `parent_id`, `name`, `column_values`, `position`) VALUES (422, '2055888741', 1, 2, NULL, 'HR', '{"col_1": "01.จัดทำตารางประมาณการณ์ MP เพื่อส่งให้ Sale หรือ After Sale ส่งแจ้งนักลงทุน, 02.ประกาศรับสมัครพนักงานในเพจ Facebook HR Nigiwai / HR Durianism / โมเดลอื่นๆ  (ยิง Ads ทั่วประเทศ), 03.ประกาศรับสมัครพนักงานในเพจ Facebook ของสาขา (ยิง Ads เฉพาะพื้นที่), 08.สัมภาษณ์พนักงานเบื้องต้นรอบแรก, 06.สรรหาตามตารางประมาณการณ์ MP ในแต่ละโมเดล, 22.นำส่งไฟล์ข้อมูลเงินเดือนตั้งต้นและเอกสารที่กี่ยวข้องกับฝ่ายบุคคล, 18.แจ้งตารางทีมเซ็ต(จริง) เพื่อให้เซลล์เรียกเก็บค่าใช้จ่ายก่อนทีมเซ็ตเดินทาง 1-2 สัปดาห์, 17.พนักงานเริ่มเทรนงานภาคทฤษฎี + OJT, 09.ส่งพนักงานเทสมือตามสาขาที่ HR พิจารณา, 14.แจ้งนักลงทุนให้ทราบถึงข้อมูลการไปเทรนของพนักงานเช่น เทรนสาขาไหน จำนวนกี่วัน มีค่าใช้จ่ายอะไรบ้าง, 07.สร้างกลุ่มพนักงาน / ดึงพนักงานเข้ากลุ่ม, 05.ประกาศรับสมัครพนักงานในกลุ่ม Facebook ตามพื้นที่, 11.แจ้งนักลงทุนของสาขาให้ทราบเกี่ยวกับข้อมูลผู้สมัครที่ผ่านการสัมภาษณ์ในแต่ละตำแหน่งและเงินเดือน, 15.ทำเรื่องเบิกเงิน Cash Flow สำหรับค่าใช้จ่ายเกี่ยวกับพนักงาน เช่น เงินเดือนช่วงเทรน ค่าที่พัก ค่าเดินทาง เป็นต้น, 04.ประกาศรับสมัครพนักงานในกลุ่ม Facebook อาชีพนั้นๆ เช่น เพจเชฟอาหารญี่ปุ่น, 23.ดำเนินการแจ้งเรียกเก็บ OT ตามเอกสารการบันทึกเวลาหน้าสาขา ภายใน 7-14 วันหลังจากตราวจสอบข้อมูลที่ถูกต้องเรียบร้อบแล้ว, 20.ก่อนทีมเซทลงสาขา 1-2 สัปดาห์ นำส่งข้อมูลเอกสารใบสมัครพนักงานและ ข้อมูลเงินเดือนให้ทีมเซ็ต, 16.แจ้งพนักงานให้ทราบเกี่ยวกับสาขาที่เข้ารับการเทรน ที่พักและวันเริ่มเทรน, 12.ติดต่อประสานงานขออนุญาตนักลงทุนสาขาในใกล้เคียง เพื่อจะขอส่งพนักงานไปเทรนในสาขานั้นๆ, 21.แจ้งวัน-เวลา ให้พนักงานเทรนเข้าสาขาก่อน วัน Soft 1 สัปดาห์ เพื่อเตรียมตัว, 13.ติดต่อหาที่พักและการเดินทางให้กับพนักงานในระหว่างการเทรน, สรรหาตามตารางประมาณการณ์ MP ตามแจ้ง ในโมเดลใหม่, 10.คัดเลือกพนักงาน พร้อมทั้งแจ้งเงินเดือนพนักงานและการเทรนแก่พนักงาน, 19.นัดทีมเซ็ตเพื่อแจ้งรายละเอียดและวันปฏิบัติงานก่อนเข้าสาขา", "col_2": 63, "col_7": "Working on it", "col_8": "100%, 100%, 100%, 0%, 100%, 100%, 100%, 0%, 0%, 0%, 100%, 0%, 100%, 0%, 100%, 100%, 100%, 0%, 100%, 0%, 0%, 100%, 100%, 100%", "col_11": 1500, "col_13": "0%", "col_17": "PP IT Dec 15, 2025 9:45 AM"}', 7.0);
